-- Coder Nation site: leads from the contact form, site settings, admin accounts and sessions.
-- MySQL 8 / MariaDB 10.6+. Ids are UUIDs generated by the app. All timestamps are UTC.

create table leads (
  id char(36) not null primary key default (uuid()),
  name varchar(120) not null,
  phone varchar(30) not null,
  email varchar(254) null,
  service varchar(80) null,
  message varchar(2000) null,
  status varchar(20) not null default 'new',
  note varchar(2000) not null default '',
  source varchar(40) not null default 'website',
  -- HMAC of the visitor's IP with a server secret: enough to spot repeats, useless to identify anyone.
  ip_hash varchar(64) null,
  user_agent varchar(300) null,
  created_at datetime(3) not null default current_timestamp(3),
  updated_at datetime(3) not null default current_timestamp(3),
  constraint leads_name_len check (char_length(name) between 2 and 120),
  constraint leads_phone_len check (char_length(phone) between 6 and 30),
  constraint leads_status_ok check (status in ('new', 'contacted', 'closed')),
  index leads_status_created_idx (status, created_at),
  index leads_created_idx (created_at)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

-- One JSON document under the name 'site' (validated by the app before it is written).
create table settings (
  name varchar(40) not null primary key,
  value json not null,
  updated_at datetime(3) not null default current_timestamp(3)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

create table admins (
  id char(36) not null primary key default (uuid()),
  -- utf8mb4_bin: the unique index and the lowercase check must both be exact, not case-insensitive.
  email varchar(254) character set utf8mb4 collate utf8mb4_bin not null unique,
  password_hash varchar(255) not null,
  created_at datetime(3) not null default current_timestamp(3),
  last_login_at datetime(3) null,
  constraint admins_email_lower check (email = lower(email))
) default charset utf8mb4 collate utf8mb4_unicode_ci;

-- The browser holds a random token; only its SHA-256 is stored, so a leaked table cannot be replayed.
create table sessions (
  id char(36) not null primary key default (uuid()),
  admin_id char(36) not null,
  token_hash varchar(64) not null unique,
  expires_at datetime(3) not null,
  created_at datetime(3) not null default current_timestamp(3),
  user_agent varchar(300) null,
  constraint sessions_admin_fk foreign key (admin_id) references admins (id) on delete cascade,
  index sessions_admin_idx (admin_id),
  index sessions_expires_idx (expires_at)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

-- Fixed-window counters for the public form and the login (see src/server/rate-limit.ts).
create table rate_limits (
  name varchar(200) not null primary key,
  hits int not null,
  window_start datetime(3) not null
) default charset utf8mb4 collate utf8mb4_unicode_ci;
